   결과: MD_Item 235 (ASSY 77 · SUB 104 · MATERIAL 54),
         MD_BomVersion 178, MD_Bom 430, MD_Vendor 8, SCM_ItemVendor 52
   적용: sqlcmd -S <server> -d AMES_DEV -U ames_app -P <pw> -f 65001 -I -b -i dist/seed_md_item_bom_master_list.sql
   ------------------------------------------------------------------ */
SET NOCOUNT ON;
SET XACT_ABORT ON;

-- ── §0 가드: 재적재 대상 밖에서 FK 로 품목·BOM 을 참조하는 행이 있으면 중단 ──────
DECLARE @guard nvarchar(max);
SELECT @guard = STRING_AGG(CAST(N'SELECT N''' + t.name + N''' WHERE EXISTS (SELECT 1 FROM '
                  + QUOTENAME(SCHEMA_NAME(t.schema_id)) + N'.' + QUOTENAME(t.name) + N')' AS nvarchar(max)), N' UNION ALL ')
FROM   sys.tables t
WHERE  t.object_id IN (SELECT fk.parent_object_id FROM sys.foreign_keys fk
                       WHERE fk.referenced_object_id IN (OBJECT_ID(N'dbo.MD_Item'), OBJECT_ID(N'dbo.MD_BomVersion'), OBJECT_ID(N'dbo.MD_Bom')))
  AND  t.object_id NOT IN (OBJECT_ID(N'dbo.MD_Item'), OBJECT_ID(N'dbo.MD_BomVersion'), OBJECT_ID(N'dbo.MD_Bom'), OBJECT_ID(N'dbo.SCM_ItemVendor'));
DECLARE @blocked TABLE (TableName sysname);
IF @guard IS NOT NULL INSERT @blocked EXEC (@guard);
IF EXISTS (SELECT 1 FROM @blocked)
BEGIN
    DECLARE @msg nvarchar(2048) = N'품목·BOM 을 FK 로 참조하는 행이 있어 전체 재적재를 할 수 없다: '
                                + (SELECT STRING_AGG(TableName, N', ') FROM @blocked);
    THROW 50001, @msg, 1;
END;

BEGIN TRAN;

-- ── §1 MD_Uom: SH(시트) ─────────────────────────────────────────────
SELECT 'SH', 'Sheet', 'QTY', 0, 1, 3, 'sh', 1, 'admin', SYSDATETIME()
WHERE  NOT EXISTS (SELECT 1 FROM dbo.MD_Uom WHERE UOMCode = 'SH');
PRINT CONCAT(N'§1 MD_Uom 추가: ', @@ROWCOUNT, N' 건');

-- ── §2 ITEM_CATEGORY 공통코드 ───────────────────────────────────────
SELECT 'ITEM_CATEGORY_' + v.CodeValue, 'ITEM_CATEGORY', v.CodeValue, v.CodeName, v.CodeNameEn, NULL, v.SortOrder, v.Attribute1, 1, NULL, 'admin@ames.local', SYSDATETIME()
FROM  (VALUES
        ('RESIN', N'레진', N'Resin', N'MATERIAL', 94),
        ('CHEM', N'부자재', N'Chemical', N'MATERIAL', 95),
        ('FASTENER', N'체결부품', N'Fastener', N'MATERIAL', 96),
        ('PART', N'구매부품', N'Part', N'MATERIAL', 97)
      ) v (CodeValue, CodeName, CodeNameEn, Attribute1, SortOrder)
WHERE  NOT EXISTS (SELECT 1 FROM dbo.MD_CodeItem c WHERE c.CodeID = 'ITEM_CATEGORY_' + v.CodeValue);
PRINT CONCAT(N'§2 ITEM_CATEGORY 추가: ', @@ROWCOUNT, N' 건');

-- ── §3 MD_Vendor ────────────────────────────────────────────────────
SELECT v.VendorID, v.VendorName, v.VendorType, v.VendorCategory, 1, 'admin', SYSDATETIME()
FROM  (VALUES
        ('KD-HANWHA', N'HANWHA', 'CKD', N'Fabric'),
        ('KD-KLUEBER', N'KLUEBER', 'CKD', N'Lubricant'),
        ('KD-KOLON', N'KOLON GLOTECH', 'CKD', N'Fabric'),
        ('KD-SIKA', N'SIKA', 'CKD', N'Adhesive'),
        ('KD-SUNGCHANG', N'SUNGCHANG PRECISION', 'CKD', N'Fastener'),
        ('LP-DEAHA', N'DEAHA', 'LOCAL', N'Resin'),
        ('LP-HYUNDAIEP', N'HYUNDAI EP', 'LOCAL', N'Resin'),
        ('LP-KRA', N'KRA', 'LOCAL', N'Interior Trim')
      ) v (VendorID, VendorName, VendorType, VendorCategory)
WHERE  NOT EXISTS (SELECT 1 FROM dbo.MD_Vendor x WHERE x.VendorID = v.VendorID);
PRINT CONCAT(N'§3 MD_Vendor 추가: ', @@ROWCOUNT, N' 건');

-- ── §4 전체 삭제 ────────────────────────────────────────────────────
DELETE dbo.SCM_ItemVendor;  PRINT CONCAT(N'§4 SCM_ItemVendor 삭제: ', @@ROWCOUNT, N' 건');
DELETE dbo.MD_Bom;          PRINT CONCAT(N'§4 MD_Bom 삭제: ', @@ROWCOUNT, N' 건');
DELETE dbo.MD_BomVersion;   PRINT CONCAT(N'§4 MD_BomVersion 삭제: ', @@ROWCOUNT, N' 건');
DELETE dbo.MD_Item;         PRINT CONCAT(N'§4 MD_Item 삭제: ', @@ROWCOUNT, N' 건');

-- ── §5 MD_Item ──────────────────────────────────────────────────────
DECLARE @n5 int = @@ROWCOUNT;
IF @n5 <> 235 THROW 50002, N'MD_Item 행 수 불일치', 1;
PRINT CONCAT(N'§5 MD_Item 추가: ', @n5, N' 건');

-- ── §6 MD_BomVersion (부모 품번마다 1건) ────────────────────────────
DECLARE @n6 int = @@ROWCOUNT;
IF @n6 <> 178 THROW 50003, N'MD_BomVersion 행 수 불일치', 1;
PRINT CONCAT(N'§6 MD_BomVersion 추가: ', @n6, N' 건');

-- ── §7 MD_Bom (직접 자식, Level 1) ──────────────────────────────────
DECLARE @n7 int = @@ROWCOUNT;
IF @n7 <> 430 THROW 50004, N'MD_Bom 행 수 불일치', 1;
IF EXISTS (SELECT 1 FROM dbo.MD_Bom b WHERE NOT EXISTS (SELECT 1 FROM dbo.MD_Item i WHERE i.ItemNo = b.ParentItemNo)
                                        OR NOT EXISTS (SELECT 1 FROM dbo.MD_Item i WHERE i.ItemNo = b.CompItemNo))
    THROW 50005, N'MD_Bom 에 MD_Item 에 없는 품번이 있다', 1;
PRINT CONCAT(N'§7 MD_Bom 추가: ', @n7, N' 건');

-- ── §8 SCM_ItemVendor (구매 자재 → 공급사) ──────────────────────────
DECLARE @n8 int = @@ROWCOUNT;
IF @n8 <> 52 THROW 50006, N'SCM_ItemVendor 행 수 불일치', 1;
PRINT CONCAT(N'§8 SCM_ItemVendor 추가: ', @n8, N' 건');

COMMIT;
GO

-- 확인
SELECT ItemType, COUNT(*) AS Items FROM dbo.MD_Item GROUP BY ItemType ORDER BY ItemType;
SELECT (SELECT COUNT(*) FROM dbo.MD_BomVersion) AS Versions, (SELECT COUNT(*) FROM dbo.MD_Bom) AS Lines,
       (SELECT COUNT(*) FROM dbo.MD_Item i WHERE i.ItemType IN ('ASSY','SUB')
          AND NOT EXISTS (SELECT 1 FROM dbo.MD_Bom b WHERE b.ParentItemNo = i.ItemNo)) AS MakeItemsWithoutBom;
GO
